head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gOvrdue_occr_dd;
scwin.gSDate;
scwin.gEDate;
scwin.gPeriodTp;
scwin.vScrenID = 'ULDSTF39201.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    //var y_day = cGetMinusDate2(cGetToday("yyyymmdd"), 1);

    scwin.gSDate = $c.frame.path("../").scwin.gSDate;
    scwin.gEDate = $c.frame.path("../").scwin.gEDate;
    scwin.gPeriodTp = $c.frame.path("../").scwin.gPeriodTp;
    $c.stf.setObjectValue(edt_SDate, scwin.gSDate);
    $c.stf.setObjectValue(edt_EDate, scwin.gEDate);
    $c.stf.setObjectValue(cmb_PeriodTp, scwin.gPeriodTp);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !개선계획서--;
검색-- > function() {
    var url = "/CorpBndPrincInt.do?method=listCorpBndPrincIntDetail";
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDate); //연체발생일자 시작일
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDate); //연체발생일자 종료일
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_list.DataID = encodeURI(url);
    dts_list.reset();
    $c.cm.ShowWin(dts_list);
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    if (dts_list.errorMsg) {
        $c.win.alert(dts_list.errorMsg);
    } else {

    }
    $c.cm.CloseWin();
};
scwin.dts_list_OnLoadError = function() {
    $c.stf.alert_error(dts_list);
    $c.cm.CloseWin();
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_Init();

    // 패널라운드 처리
    //PanelToGroupBox(panel_1);

    //fn_SetCode();
    //fn_GetParentValue();
    fn_Search();
};
scwin.btn_Tab1_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_Tab1_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Search_onclick = function() {
    fn_Search(); //조회 버튼

};
scwin.grd_list_OnDblClick = async function(row, colid) {
    if (colid == "INPUT_SEQ") {
        scwin.gOvrdue_occr_dd = dts_list.getCellData(row, "CBPI_OVRDUE_OCCR_DD");
        await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39202.gfm", scwin.gOvrdue_occr_dd.substring(0, 4) + "-" + scwin.gOvrdue_occr_dd.substring(4, 6) + "-" + scwin.gOvrdue_occr_dd.substring(6, 8) + " 등록내역", 300, 100, 680, 400, "window");
    }
};
